        if slop == 1 and len(tokens) == len(set(tokens)):
            try:
                # Get term IDs using self.term_dict
                term_ids = [self.term_dict[token] for token in tokens]
                # Use term positions to directly calculate phrase frequencies
                return self.posns.phrase_freqs(term_ids)
            except TermMissingError:
                # Handle TermMissingError and return zeros or handle it differently
                return np.zeros(len(self))
        else:
            # Delegate calculation to phrase_freq_every_diff for non-1 slop or non-unique tokens
            return self.phrase_freq_every_diff(tokens, slop)
